//! Replays the golden corpus generated by
//! `electricity/scripts/generate_regex_corpus.py` -- real output from
//! Circuitry's own `RegexPlugin.execute` (`plugins/regex.py`) -- against
//! this crate's own port (`electricity_tools::regex::RegexPlugin`).
//!
//! Comparison follows issue #479's own ruling 3: Circuitry's own
//! messages (every parameter check, `sub`'s own `replacement`/`count`
//! errors, and `regex: unknown flag ...`) are compared exactly; a
//! `re.error`-shaped message -- wrapped with the `regex: invalid
//! pattern: ` prefix or not (a template error) -- is compared only for
//! "both engines failed, with the same prefix", never byte for byte,
//! since `fancy-regex`'s own parser error wording is never going to
//! match CPython's `re` exactly.
//!
//! The corpus is checked in (`tests/golden/regex_corpus.json`); CI
//! separately regenerates it with Python 3.11 and fails the build if it
//! differs (`.github/workflows/electricity-generated.yml`), so this test
//! only needs to trust the committed file.

use electricity_tools::{CheckResult, ToolCall, ToolPlugin};
use electricity_value::{CancellationToken, Dict, IntValue, Value};
use serde::Deserialize;

#[derive(Deserialize, Debug, Clone)]
#[serde(tag = "t")]
enum TaggedValue {
    #[serde(rename = "none")]
    None,
    #[serde(rename = "bool")]
    Bool { v: bool },
    #[serde(rename = "int")]
    Int { v: String },
    #[serde(rename = "float")]
    Float { bits: String },
    #[serde(rename = "str")]
    Str { v: String },
    #[serde(rename = "list")]
    List { v: Vec<TaggedValue> },
    #[serde(rename = "dict")]
    Dict { v: Vec<(TaggedValue, TaggedValue)> },
}

impl From<TaggedValue> for Value {
    fn from(tagged: TaggedValue) -> Self {
        match tagged {
            TaggedValue::None => Value::None,
            TaggedValue::Bool { v } => Value::Bool(v),
            TaggedValue::Int { v } => {
                Value::Int(IntValue::parse_decimal(&v).expect("valid decimal integer"))
            }
            TaggedValue::Float { bits } => {
                let bits = u64::from_str_radix(&bits, 16).expect("valid hex bit pattern");
                Value::Float(f64::from_bits(bits))
            }
            TaggedValue::Str { v } => Value::Str(v),
            TaggedValue::List { v } => Value::List(v.into_iter().map(Value::from).collect()),
            TaggedValue::Dict { v } => {
                let mut dict = Dict::new();
                for (k, val) in v {
                    dict.insert(Value::from(k), Value::from(val));
                }
                Value::Dict(dict)
            }
        }
    }
}

#[derive(Deserialize)]
struct Case {
    case: String,
    params: TaggedValue,
    ok: Option<TaggedValue>,
    raw: Option<TaggedValue>,
    err: Option<String>,
    is_re_error: bool,
    is_invalid_pattern: bool,
}

#[derive(Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}

static NONE: Value = Value::None;

fn call(token: &CancellationToken) -> ToolCall<'_> {
    ToolCall {
        timeout_seconds: 30,
        config: &NONE,
        token,
        armed: false,
    }
}

#[tokio::test]
async fn replays_the_regex_corpus() {
    let text = include_str!("golden/regex_corpus.json");
    let corpus: Corpus = serde_json::from_str(text).expect("valid corpus JSON");
    assert!(
        !corpus.cases.is_empty(),
        "the corpus should never be committed empty"
    );

    let plugin = electricity_tools::regex::RegexPlugin;
    let token = CancellationToken::new();
    let mut failures = Vec::new();

    for case in corpus.cases {
        let params: Value = case.params.clone().into();
        let result = plugin.execute(params, &call(&token)).await;

        match (case.ok, case.err.as_deref()) {
            (Some(expected_ok), None) => match result {
                Ok(tool_result) => {
                    let expected_value: Value = expected_ok.into();
                    if tool_result.value != expected_value {
                        failures.push(format!(
                            "{}: value mismatch: expected {:?}, got {:?}",
                            case.case, expected_value, tool_result.value
                        ));
                    }
                    if let Some(expected_raw) = case.raw {
                        let expected_raw: Value = expected_raw.into();
                        if tool_result.raw != expected_raw {
                            failures.push(format!(
                                "{}: raw mismatch: expected {:?}, got {:?}",
                                case.case, expected_raw, tool_result.raw
                            ));
                        }
                    }
                }
                Err(e) => {
                    failures.push(format!(
                        "{}: expected success, electricity failed: {}",
                        case.case, e.message
                    ));
                }
            },
            (None, Some(expected_err)) => match result {
                Ok(tool_result) => {
                    failures.push(format!(
                        "{}: expected failure {:?}, electricity succeeded with {:?}",
                        case.case, expected_err, tool_result.value
                    ));
                }
                Err(e) => {
                    if case.is_re_error {
                        // `re.error`-shaped, wrapped or not -- compared
                        // by location only (both fail, same prefix).
                        let prefix = if case.is_invalid_pattern {
                            "regex: invalid pattern: "
                        } else {
                            ""
                        };
                        if !e.message.starts_with(prefix) {
                            failures.push(format!(
                                "{}: error prefix mismatch: expected prefix {:?}, got {:?}",
                                case.case, prefix, e.message
                            ));
                        }
                    } else if e.message != expected_err {
                        failures.push(format!(
                            "{}: error text mismatch: expected {:?}, got {:?}",
                            case.case, expected_err, e.message
                        ));
                    }
                }
            },
            _ => unreachable!("a corpus case has exactly one of ok/err set"),
        }
    }

    assert!(
        failures.is_empty(),
        "regex corpus replay failures:\n{}",
        failures.join("\n")
    );
}

#[test]
fn check_result_is_always_ok() {
    let plugin = electricity_tools::regex::RegexPlugin;
    let check: CheckResult = plugin.check();
    assert!(check.ok);
    assert!(check.missing.is_empty());
    assert!(check.message.is_none());
}
